shader.fragmentShader:
#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_image;
uniform float u_time;
uniform float u_intensity;
void main() {
  vec4 c = texture(u_image, v_uv);
  float leak = max(0.0, 1.0 - distance(v_uv, vec2(0.1, 0.1)) * 1.5) * (0.8 + 0.2 * sin(u_time * 2.0)) * u_intensity;
  vec3 warm = vec3(1.0, 0.55, 0.15);
  fragColor = vec4(c.rgb + warm * leak * 0.45, c.a);
}
